begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.login(i integer) returns void language plpgsql as $$ begin
 perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','38080000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true);
end $$;
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000',('38080000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','reimbursement-test-'||i||'@example.test','{}','{}',now(),now(),'','','','' from generate_series(1,6) i;
select pg_temp.login(1);
create temp table ctx as select public.create_project('Payment links fixture','UTC','GBP','2026-01-01') id;
create temp table cat as with c as(insert into public.project_areas(project_id,title) select id,'Villa' from ctx returning id) select * from c;
set local role postgres;
insert into public.project_members(project_id,user_id,display_name,role,status)
select ctx.id,('38080000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Reimbursement member '||i,case when i=4 then 'viewer' else 'member' end::public.member_role,'active' from ctx,generate_series(2,4) i;
create temp table members as select right(user_id::text,1)::int n,id from public.project_members where project_id=(select id from ctx);
grant select on members to authenticated;
select pg_temp.login(1);
create temp table activity as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Villa","kind":"other","activity_type":"task","estimated_cost_minor":90000}',null)).id;
select public.set_activity_cost_split((select id from activity),jsonb_build_object('mode','even','cost',90000,'members',(select jsonb_agg(id order by id) from members where n<=3)));
create temp table payment as with p as(insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,activity.id,members.id,'full','outgoing','paid',90000,current_date from ctx,activity,members where n=1 returning id) select * from p;
insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select ctx.id,activity.id,'Vendor schedule',90000,current_date+30 from ctx,activity;
create temp table before_schedules as select jsonb_agg(to_jsonb(s) order by payment_schedule_id) doc from public.v_activity_payment_schedule_financials s where project_id=(select id from ctx);
create temp table before_financial as select to_jsonb(f) doc from public.v_project_financials f where project_id=(select id from ctx);
create temp table before_balances as select jsonb_agg(to_jsonb(s) order by member_id) doc from public.v_activity_member_settlements s where commitment_id=(select id from activity);
create temp table before_member_balances as select jsonb_agg(to_jsonb(s) order by member_id) doc from public.v_member_balances s where project_id=(select id from ctx);
create temp table before_shares as select jsonb_agg(to_jsonb(s) order by member_id) doc from public.cost_shares s where commitment_id=(select id from activity);
create temp table request_a as select public.create_reimbursement((select id from payment),(select id from members where n=2),30000) id;
create temp table request_b as select public.create_reimbursement((select id from payment),(select id from members where n=3),30000) id;
create function pg_temp.financial_snapshot() returns jsonb language sql as $$
 select jsonb_build_object('project',(select jsonb_agg(to_jsonb(t)) from public.v_project_financials t where project_id=(select id from ctx)),
 'activity',(select jsonb_agg(to_jsonb(t) order by member_id) from public.v_activity_member_settlements t where project_id=(select id from ctx)),
 'members',(select jsonb_agg(to_jsonb(t) order by member_id) from public.v_member_balances t where project_id=(select id from ctx)),
 'schedules',(select jsonb_agg(to_jsonb(t) order by payment_schedule_id) from public.v_activity_payment_schedule_financials t where project_id=(select id from ctx)),
 'payments',(select jsonb_agg(to_jsonb(t) order by id) from public.payments t where project_id=(select id from ctx)),
 'shares',(select jsonb_agg(to_jsonb(t) order by member_id) from public.cost_shares t where project_id=(select id from ctx)),
 'requests',(select jsonb_agg(to_jsonb(t) order by id) from public.reimbursement_requests t where project_id=(select id from ctx)),
 'health',(select jsonb_agg(to_jsonb(t) order by code,subject_id) from public.get_project_health((select id from ctx)) t));
$$;
create temp table baseline as select pg_temp.financial_snapshot() doc;
create temp table first_link as select public.save_my_payment_link('monzo',' HTTPS://MONZO.ME/example?ref=Case%20Kept#Fragment ') id;
select is((select payment_url from public.list_my_payment_links()),'https://monzo.me/example?ref=Case%20Kept#Fragment','Canonical scheme/host, opaque suffix retained');
select is((select count(*)::int from public.list_my_payment_links() where is_default),0,'Zero default allowed');
create temp table second_link as select public.save_my_payment_link('revolut','https://revolut.me/example') id;
select lives_ok($$select public.set_default_payment_link((select id from first_link))$$,'Owner sets default');
select public.set_default_payment_link((select id from second_link));
select is((select count(*)::int from public.list_my_payment_links() where is_default),1,'One default after atomic switch');
select is((select id from public.list_my_payment_links() limit 1),(select id from second_link),'Default ordered first');
select lives_ok($$select public.save_my_payment_link('custom','https://payments.example.com/Case?x=1#ok','Personal link',(select id from second_link))$$,'Edit provider and revalidate');
select is((select provider from public.list_my_payment_links() where id=(select id from second_link)),'custom','Provider edit persisted');
select is(pg_temp.financial_snapshot(),(select doc from baseline),'Create edit default leave all financial state unchanged');
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_a))),0,'Creditor gets no debtor payment options');
select throws_ok($$update public.user_payment_links set payment_url='https://evil.com' where id=(select id from first_link)$$,'42501',null,'Direct update denied');
select throws_ok($$insert into public.user_payment_links(user_id,provider,payment_url,display_label) values(auth.uid(),'custom','javascript:alert(1)','bad')$$,'42501',null,'Unsafe direct insert denied');
select throws_ok($$delete from public.user_payment_links where id=(select id from first_link)$$,'42501',null,'Direct delete denied');
select throws_ok($$select public.save_my_payment_link('monzo','http://monzo.me/example','Test')$$,'P0001',null,'HTTP rejected');
select throws_ok($$select public.save_my_payment_link('monzo','javascript:alert(1)','Test')$$,'P0001',null,'JavaScript rejected');
select throws_ok($$select public.save_my_payment_link('custom','data:text/html,hi','Test')$$,'P0001',null,'Data URI rejected');
select throws_ok($$select public.save_my_payment_link('monzo','https://monzo.me.evil.com/example','Test')$$,'P0001',null,'Host suffix spoof rejected');
select throws_ok($$select public.save_my_payment_link('monzo','https://evil.com/?next=https://monzo.me/example','Test')$$,'P0001',null,'Query spoof rejected');
select throws_ok($$select public.save_my_payment_link('revolut','https://monzo.me/example','Test')$$,'P0001',null,'Wrong provider rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://user:pass@example.com/path','Test')$$,'P0001',null,'Userinfo rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://127.0.0.1/path','Test')$$,'P0001',null,'Loopback rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://10.0.0.1/path','Test')$$,'P0001',null,'Private IP rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://172.16.0.1/path','Test')$$,'P0001',null,'Private IP 172 rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://192.168.1.2/path','Test')$$,'P0001',null,'Private IP 192 rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://169.254.169.254/path','Test')$$,'P0001',null,'Link-local rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://[::1]/path','Test')$$,'P0001',null,'IPv6 rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://2130706433/path','Test')$$,'P0001',null,'Integer IP rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://0x7f000001/path','Test')$$,'P0001',null,'Hex IP rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://example.local/path','Test')$$,'P0001',null,'Local suffix rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://localhost/path','Test')$$,'P0001',null,'Localhost rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://example.com:443/path','Test')$$,'P0001',null,'Explicit port rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://example..com/path','Test')$$,'P0001',null,'Empty DNS label rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://-bad.example.com/path','Test')$$,'P0001',null,'Invalid DNS label rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://example.com/%zz','Test')$$,'P0001',null,'Bad percent escape rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://example.com\@monzo.me/path','Test')$$,'P0001',null,'Backslash rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://example.com/a b','Test')$$,'P0001',null,'Space rejected');
select throws_ok($$select public.save_my_payment_link('monzo','https://monzo.me/','Test')$$,'P0001',null,'Missing personal path rejected');
select throws_ok($$select public.save_my_payment_link('monzo','','Test')$$,'P0001',null,'Blank rejected');
select throws_ok($$select public.save_my_payment_link('unknown','https://example.com/path','Test')$$,'P0001',null,'Unknown provider rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://example.com/'||repeat('x',2048),'Long')$$,'P0001',null,'Excessive length rejected');
select throws_ok($$select public.save_my_payment_link('custom','https://example.com/path','')$$,'P0001',null,'Custom label required');
select throws_ok($$select public.save_my_payment_link('revolut','https://monzo.me/example',null,(select id from first_link))$$,'P0001',null,'Provider edit invalidates old host');
select pg_temp.login(2);
select is((select count(*)::int from public.list_my_payment_links()),0,'No arbitrary owner list');
select is((select count(*)::int from public.user_payment_links),0,'Direct table RLS owner only');
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_a))),2,'Debtor sees enabled creditor options');
select is((select id from public.get_reimbursement_payment_options((select id from request_a)) limit 1),(select id from second_link),'Debtor default first');
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_b))),0,'Unrelated debtor request hidden');
select throws_ok($$select public.save_my_payment_link('monzo','https://monzo.me/attacker',null,(select id from first_link))$$,'42501',null,'Other Member cannot edit');
select throws_ok($$select public.delete_my_payment_link((select id from first_link))$$,'42501',null,'Other Member cannot delete');
select throws_ok($$select public.set_default_payment_link((select id from first_link))$$,'42501',null,'Other Member cannot set default');
select pg_temp.login(4);
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_a))),0,'Unrelated Viewer cannot resolve options');
select throws_ok($$select public.save_my_payment_link('monzo','https://monzo.me/attacker',null,(select id from first_link))$$,'42501',null,'Viewer cannot edit another user');
select pg_temp.login(5);
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_a))),0,'Outsider cannot resolve options');
create temp table other as select public.create_project('Other link project','UTC','GBP','2026-01-01') id;
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_a))),0,'Cross-project Organizer cannot resolve options');
select pg_temp.login(1);
update public.project_members set role='viewer' where id=(select id from members where n=3);
select pg_temp.login(3);
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_b))),2,'Viewer debtor can pay own valid request');
select pg_temp.login(1);
select public.save_my_payment_link('custom','https://payments.example.com/Case?x=1#ok','Personal link',(select id from second_link),false);
select is((select count(*)::int from public.list_my_payment_links() where is_default),0,'Disable default clears default');
select pg_temp.login(2);
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_a))),1,'Disabled link not returned');
select pg_temp.login(1);
select public.save_my_payment_link('revolut','https://revolut.me/updated',null,(select id from second_link),true);
select public.set_default_payment_link((select id from second_link));
select public.delete_my_payment_link((select id from second_link));
select lives_ok($$select public.delete_my_payment_link((select id from second_link))$$,'Repeated removal safe');
select is((select count(*)::int from public.list_my_payment_links() where is_default),0,'Deleted default promotes none');
select is(pg_temp.financial_snapshot(),(select doc from baseline),'Disable/delete leave all financial state unchanged');
set local role postgres;
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.user_payment_links'::regclass),'ENABLE/FORCE RLS');
select ok(not has_table_privilege('service_role','public.user_payment_links','INSERT') and not has_function_privilege('service_role','public.save_my_payment_link(text,text,text,uuid,boolean)','EXECUTE'),'Service role unsafe writes revoked');
select ok(not exists(select 1 from public.audit_log where entity_type='user_payment_links' and (coalesce(before,'{}') ?| array['payment_url','display_label'] or coalesce(after,'{}') ?| array['payment_url','display_label'])),'Audit redacts URLs and labels');
select ok(exists(select 1 from public.audit_log where entity_type='user_payment_links' and entity_id=(select id from first_link)),'Metadata audit exists');
select ok(not exists(select 1 from app.domain_event_types where event_type like 'payment_link.%'),'No unnecessary events');
select ok(not exists(select 1 from app.domain_events where project_id=(select id from ctx) and payload::text ~ 'monzo.me|revolut.me|payments.example.com'),'No URL in domain events');
select ok(not exists(select 1 from public.notifications where project_id=(select id from ctx) and to_jsonb(notifications)::text ~ 'monzo.me|revolut.me|payments.example.com'),'No URL in notifications');
select pg_temp.login(1);
select ok(not exists(select 1 from public.get_project_health((select id from ctx)) h where to_jsonb(h)::text ~ 'monzo.me|revolut.me|payments.example.com'),'No URL in Health');
select ok(not exists(select 1 from public.users u where to_jsonb(u)::text ~ 'monzo.me|revolut.me|payments.example.com'),'No URL in profile');
select ok(not exists(select 1 from public.v_member_directory m where project_id=(select id from ctx) and to_jsonb(m)::text ~ 'monzo.me|revolut.me|payments.example.com'),'No URL in member directory');
-- Another creditor: Organizer request visibility must not reveal personal links.
create temp table multi as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Other creditor","kind":"other","activity_type":"task","estimated_cost_minor":90000}',null)).id;
select public.set_activity_cost_split((select id from multi),jsonb_build_object('mode','even','cost',90000,'members',(select jsonb_agg(id order by id) from members where n<=3)));
insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,multi.id,members.id,'full','outgoing','paid',30000,current_date from ctx,multi,members where n=1;
select pg_temp.login(2);
create temp table other_link as select public.save_my_payment_link('monzo','https://monzo.me/member') id;
create temp table other_payment as with p as(insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,multi.id,members.id,'full','outgoing','paid',60000,current_date from ctx,multi,members where n=2 returning id) select * from p;
create temp table other_request as select public.create_reimbursement((select id from other_payment),(select id from members where n=3),30000) id;
select pg_temp.login(1);
select is((select count(*)::int from public.v_reimbursements where id=(select id from other_request)),1,'Organizer can read other parties request');
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from other_request))),0,'Organizer privilege does not reveal other creditor URL');
select throws_ok($$select public.delete_my_payment_link((select id from other_link))$$,'42501',null,'Organizer cannot delete another member personal link');
select throws_ok($$select public.save_my_payment_link('monzo','https://monzo.me/changed',null,(select id from other_link))$$,'42501',null,'Organizer cannot edit another member personal link');
select pg_temp.login(3);
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from other_request))),1,'Viewer debtor receives active Member creditor link');
select pg_temp.login(1);
update public.project_members set status='removed' where id=(select id from members where n=2);
select pg_temp.login(3);
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from other_request))),0,'Removed creditor link hidden');
select pg_temp.login(1);
update public.project_members set status='active' where id=(select id from members where n=2);
update public.project_members set status='removed' where id=(select id from members where n=3);
select pg_temp.login(3);
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from other_request))),0,'Removed debtor access denied');
select pg_temp.login(1);
update public.project_members set status='active' where id=(select id from members where n=3);
create temp table token as select public.regenerate_project_join_link((select id from ctx)) value;
select pg_temp.login(5);
select public.request_project_access((select value from token));
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from other_request))),0,'Pending requester no access');
select pg_temp.login(2);
select public.delete_my_payment_link((select id from other_link));
select pg_temp.login(1);
update public.projects set status='archived' where id=(select id from ctx);
select lives_ok($$select public.save_my_payment_link('monzo','https://monzo.me/changed',null,(select id from first_link))$$,'Global settings remain editable when project archived');
select pg_temp.login(2);
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_a))),0,'Archived request no payment action');
select pg_temp.login(1);
update public.projects set status='active' where id=(select id from ctx);
select public.cancel_reimbursement((select id from request_a));
select pg_temp.login(2);
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_a))),0,'Cancelled request API returns none');
select pg_temp.login(1);
insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,activity.id,members.id,'refund','incoming','paid',10000,current_date from ctx,activity,members where n=1;
select pg_temp.login(3);
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_b))),0,'Review-needed request API returns none');
select pg_temp.login(1);
select is((select count(*)::int from public.list_my_payment_links()),1,'Stale/cancelled requests do not remove personal configuration');
select public.soft_delete_project((select id from ctx));
select pg_temp.login(2);
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_a))),0,'Deleted project no options');
select pg_temp.login(1);
select public.delete_my_payment_link((select id from first_link));
select is((select count(*)::int from public.list_my_payment_links()),0,'Owner cleanup removes all live configuration');
set local role postgres;
select is((select count(*)::int from public.user_payment_links where user_id='38080000-0000-4000-8000-000000000001' and deleted_at is not null),2,'Soft-deleted configuration history retained');
select is((select count(*)::int from public.reimbursement_requests where project_id=(select id from ctx)),3,'Reimbursement history retained');
set local role anon;
select throws_ok($$select public.list_my_payment_links()$$,'42501',null,'Anonymous list denied');
select throws_ok($$select public.get_reimbursement_payment_options(null)$$,'42501',null,'Anonymous options denied');
select throws_ok($$select public.save_my_payment_link('monzo','https://monzo.me/example')$$,'42501',null,'Anonymous mutation denied');
select * from finish();
rollback;
